using System;using System.Linq;using System.Xml;using System.Collections.Generic;
namespace BeamScheduleFormatter {
class OpeningLink {public string Wall,Schedule;public int Quantity;}
static class OpeningLinks {
 public static List<OpeningItem> Resolve(IEnumerable<OpeningItem> source,IEnumerable<OpeningLink> assignments){var schedules=source.ToList();var links=assignments.ToList();var ids=schedules.ToDictionary(o=>o.Id,StringComparer.OrdinalIgnoreCase);var duplicates=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var l in links){OpeningItem item;if(string.IsNullOrWhiteSpace(l.Wall)||string.IsNullOrWhiteSpace(l.Schedule)||l.Quantity<1||l.Quantity>100000)throw new Exception("Check CHB schedule link and quantity.");if(!ids.TryGetValue(l.Schedule,out item)||item.Material=="Manual")throw new Exception("CHB schedule not found: "+l.Schedule);if(!duplicates.Add(l.Wall.Trim()+"\n"+l.Schedule.Trim()))throw new Exception("Duplicate opening schedule on wall "+l.Wall);}
  foreach(var g in links.GroupBy(l=>l.Schedule,StringComparer.OrdinalIgnoreCase))if(g.Sum(l=>(long)l.Quantity)>ids[g.Key].Quantity)throw new Exception("CHB assignments exceed total schedule quantity for "+g.Key+". Increase schedule Qty or correct wall assignments.");var result=new List<OpeningItem>();foreach(var item in schedules){var use=links.Where(l=>string.Equals(l.Schedule,item.Id,StringComparison.OrdinalIgnoreCase)).ToList();if(item.Material=="Manual"||use.Count==0){if(!string.IsNullOrWhiteSpace(item.Wall))result.Add(item);continue;}foreach(var l in use)result.Add(new OpeningItem{Id=item.Id,Description=item.Description,Wall=l.Wall,Material=item.Material,Kind=item.Kind,Width=item.Width,Height=item.Height,Quantity=l.Quantity});}foreach(var wall in result.GroupBy(o=>o.Wall,StringComparer.OrdinalIgnoreCase))if(wall.Count()>3)throw new Exception("Maximum 3 opening entries per wall group: "+wall.Key);return result;}
 public static List<OpeningLink> Read(XmlElement root){var result=new List<OpeningLink>();var section=root["OpeningAssignments"];if(section==null)return result;foreach(XmlElement e in section.SelectNodes("Link")){int qty;if(!int.TryParse(e.GetAttribute("qty"),out qty)||qty<1||qty>100000||string.IsNullOrWhiteSpace(e.GetAttribute("wall"))||string.IsNullOrWhiteSpace(e.GetAttribute("schedule")))throw new Exception("Invalid saved CHB opening assignment.");result.Add(new OpeningLink{Wall=e.GetAttribute("wall"),Schedule=e.GetAttribute("schedule"),Quantity=qty});}return result;}
 public static void Write(XmlElement root,IEnumerable<OpeningLink> links){var section=root.OwnerDocument.CreateElement("OpeningAssignments");root.AppendChild(section);foreach(var l in links){var e=root.OwnerDocument.CreateElement("Link");e.SetAttribute("wall",l.Wall);e.SetAttribute("schedule",l.Schedule);e.SetAttribute("qty",l.Quantity.ToString(System.Globalization.CultureInfo.InvariantCulture));section.AppendChild(e);}}
}
}
